import { AwsClient } from "aws4fetch";

/**
 * Where uploaded photo files live. Modules depend only on this interface:
 *  - S3-compatible bucket in production (Railway Buckets today; R2/AWS S3 work unchanged),
 *  - a local folder in development (image-storage.local.ts, Node-only),
 *  - memory in tests.
 * Keys are generated by the server (never taken from user input).
 */
export interface StoredObject {
  body: ReadableStream<Uint8Array> | Uint8Array;
  contentLength?: number;
}

export interface ImageStorage {
  readonly kind: "s3" | "local" | "memory";
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  /** Returns null when the object doesn't exist. */
  get(key: string): Promise<StoredObject | null>;
  /** Deleting a missing object is not an error. */
  delete(keys: string[]): Promise<void>;
}

export class ImageStorageError extends Error {
  constructor(
    message: string,
    public readonly status?: number,
  ) {
    super(message);
    this.name = "ImageStorageError";
  }
}

const KEY_PATTERN = /^[A-Za-z0-9][A-Za-z0-9/_.-]*$/;

/** Defence in depth: keys are server-generated, but never allow traversal or odd characters. */
export function assertValidKey(key: string): void {
  if (!KEY_PATTERN.test(key) || key.includes("..") || key.includes("//")) {
    throw new ImageStorageError("Invalid storage key");
  }
}

// ---------------------------------------------------------------------------
// S3-compatible (virtual-hosted-style URLs: https://<bucket>.<endpoint-host>/<key>)
// ---------------------------------------------------------------------------

export interface S3StorageOptions {
  endpoint: string;
  region: string;
  bucket: string;
  accessKeyId: string;
  secretAccessKey: string;
  fetch?: typeof fetch;
}

const S3_TIMEOUT_MS = 30_000;

export function createS3ImageStorage(options: S3StorageOptions): ImageStorage {
  const http = options.fetch ?? fetch;
  const signer = new AwsClient({
    accessKeyId: options.accessKeyId,
    secretAccessKey: options.secretAccessKey,
    service: "s3",
    region: options.region,
  });
  const endpoint = new URL(options.endpoint);
  const baseUrl = `${endpoint.protocol}//${options.bucket}.${endpoint.host}`;
  const objectUrl = (key: string) => {
    assertValidKey(key);
    return `${baseUrl}/${key.split("/").map(encodeURIComponent).join("/")}`;
  };

  async function send(method: string, key: string, init: { body?: Uint8Array; headers?: Record<string, string> } = {}) {
    const request = await signer.sign(objectUrl(key), {
      method,
      ...(init.headers ? { headers: init.headers } : {}),
      ...(init.body ? { body: init.body as RequestInit["body"] } : {}),
    });
    try {
      return await http(request, { signal: AbortSignal.timeout(S3_TIMEOUT_MS) });
    } catch {
      throw new ImageStorageError(`Photo storage unreachable (${method})`);
    }
  }

  return {
    kind: "s3",

    async put(key, bytes, contentType) {
      const response = await send("PUT", key, {
        body: bytes,
        headers: { "Content-Type": contentType, "Content-Length": String(bytes.byteLength) },
      });
      if (!response.ok) throw new ImageStorageError(`Photo storage rejected the upload (HTTP ${response.status})`, response.status);
      await response.body?.cancel();
    },

    async get(key) {
      const response = await send("GET", key);
      if (response.status === 404) {
        await response.body?.cancel();
        return null;
      }
      if (!response.ok || !response.body) {
        throw new ImageStorageError(`Photo storage read failed (HTTP ${response.status})`, response.status);
      }
      const length = Number(response.headers.get("content-length"));
      return { body: response.body, ...(Number.isFinite(length) && length > 0 ? { contentLength: length } : {}) };
    },

    async delete(keys) {
      for (const key of keys) {
        const response = await send("DELETE", key);
        await response.body?.cancel();
        // S3 answers 204 whether or not the object existed.
        if (!response.ok && response.status !== 404) {
          throw new ImageStorageError(`Photo storage delete failed (HTTP ${response.status})`, response.status);
        }
      }
    },
  };
}

// ---------------------------------------------------------------------------
// In-memory (tests)
// ---------------------------------------------------------------------------

export function createMemoryImageStorage(): ImageStorage & { objects: Map<string, { bytes: Uint8Array; contentType: string }> } {
  const objects = new Map<string, { bytes: Uint8Array; contentType: string }>();
  return {
    kind: "memory",
    objects,
    async put(key, bytes, contentType) {
      assertValidKey(key);
      objects.set(key, { bytes: bytes.slice(), contentType });
    },
    async get(key) {
      const found = objects.get(key);
      return found ? { body: found.bytes, contentLength: found.bytes.byteLength } : null;
    },
    async delete(keys) {
      for (const key of keys) objects.delete(key);
    },
  };
}
